"},{"node":"TestPublicRSSExcludesComments","qualified_name":"bench-repo.server.router.rss.TestPublicRSSExcludesComments","label":"Function","file":"server/router/rss/rss_test.go","start_line":19,"end_line":63,"in_degree":0,"out_degree":8,"match_lines":[21],"source":"func TestPublicRSSExcludesComments(t *testing.T) {
	ctx := context.Background()
	stores := teststore.NewTestingStore(ctx, t)
	defer stores.Close()

	user, err := stores.CreateUser(ctx, &store.User{
		Username: "rss-comment-owner",
		Role:     store.RoleUser,
		Email:    "rss-comment-owner@example.com",
	})
	require.NoError(t, err)

	parent, err := stores.CreateMemo(ctx, &store.Memo{
		UID:        "rss-public-parent",
		CreatorID:  user.ID,
		Content:    "public parent should stay in rss",
		Visibility: store.Public,
